}

export function createRoutinesListOperation(
	adapter: RoutinesListAdapter,
): RoutinesListOperation {
	return {
		descriptor: routinesListDescriptor,
		async execute(input, options) {
			const params = { page: input.page, pageSize: input.pageSize };
			const program = (
				options === undefined
					? adapter.getRoutines(params)
					: adapter.getRoutines(params, options)
			).pipe(
				Effect.map((response) => normalizeRoutinesPage(response, input)),
				Effect.catchIf(
					(error) => isExpectedReadEndOfList(error, "/v1/routines", input.page),
					() =>
						Effect.succeed({
							items: [],
							page: input.page,
							pageCount: undefined,
							expected404Outcome: "end_of_list" as const,
						}),
				),
			);
			return Effect.runPromise(program);
		},
	};
}

import {
	canonicalEndpointIdentity,
	expectedGet404Outcome,
	isHevyHttpError,
	NotFoundError,
} from "@hevy-mcp/hevy-client";

export type ExpectedReadError = "not_found" | "end_of_list";
export type ReadCollectionEndpoint = "/v1/routines" | "/v1/workouts";
export type ReadOperationError = Error | string;

/**
 * Classify only the documented read-side 404 cases.
 *
 * This function is deliberately pure. It does not inspect mutable client
 * state, perform I/O, or convert the error, so Effect programs can use it as
 * their error-channel boundary while Promise callers retain the original
 * error object.
 */
export function classifyReadError(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page?: number,
): ExpectedReadError | undefined {
	const httpError = isHevyHttpError(error)
		? error
		: error instanceof NotFoundError
			? error
			: undefined;
	if (!httpError) return undefined;
	const canonical = canonicalEndpointIdentity(httpError.endpoint);
	if (canonical !== endpoint && !canonical.startsWith(`${endpoint}/`)) {
		return undefined;
	}

	const expected = expectedGet404Outcome(
		httpError.endpoint,
		httpError.method,
		httpError.status,
		page,
	);
	if (expected === "not_found") return "not_found";
	if (expected === "end_of_list") return "end_of_list";
	return undefined;
}

export function isExpectedReadNotFound(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
): boolean {
	return classifyReadError(error, endpoint) === "not_found";
}

export function isExpectedReadEndOfList(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page: number,
): boolean {
	return page > 1 && classifyReadError(error, endpoint, page) === "end_of_list";
}

import { describe, expect, it, vi } from "vitest";
import { Effect } from "effect";

import {
	createRoutinesGetOperation,
	createRoutinesListOperation,
} from "./routines.js";
import {
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
} from "./workouts.js";

function assertCollapsedExecute(source: string): void {
	expect(source.match(/Effect\.runPromise/g)).toHaveLength(1);
	expect(source).not.toMatch(/Effect\.(tryPromise|promise)/);
	expect(source).toContain("Effect.catchIf");
}

describe("operations Effect collapse", () => {
	it("collapses workouts.get onto one Effect boundary", () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () => Effect.succeed({}),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses workouts.list onto one Effect boundary", () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () => Effect.succeed({ workouts: [] }),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses routines.get onto one Effect boundary", () => {
		const operation = createRoutinesGetOperation({
			getRoutineById: () => Effect.succeed({}),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses routines.list onto one Effect boundary", () => {
		const operation = createRoutinesListOperation({
			getRoutines: () => Effect.succeed({ routines: [] }),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("passes an Effect-capable read seam directly into execute", async () => {
		const getWorkout = vi.fn(() => Effect.succeed({ id: "workout-1" }));
		const operation = createWorkoutsGetOperation({ getWorkout });

		await expect(
			operation.execute({ workoutId: "workout-1" }),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});

		const seamResult = getWorkout.mock.results[0]?.value;
		expect(seamResult).toBeDefined();
		await expect(Effect.runPromise(seamResult)).resolves.toEqual({
			id: "workout-1",
		});
	});
});

{
	"name": "@hevy-mcp/operations",
	"version": "0.1.7",
	"private": true,
	"type": "module",
	"exports": {
		".": {
			"types": "./src/index.ts",
			"import": "./src/index.ts"
		}
	},
	"scripts": {
		"build": "tsc --noEmit -p tsconfig.json",
		"check:types": "tsc --noEmit -p tsconfig.json"
	},
	"dependencies": {
		"@hevy-mcp/hevy-client": "workspace:*",
		"effect": "^4.0.0-rc.112"
	}
}

import { describe, expect, it, vi } from "vitest";

import { createHevyClient } from "@hevy-mcp/hevy-client";
import { createOperations } from "./index.js";

type JsonValue = string | number | boolean | null | JsonObject | JsonValue[];
type JsonObject = { readonly [key: string]: JsonValue };

function response(data: JsonObject, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "content-type": "application/json" },
	});
}

describe("createOperations public client injection", () => {
	it("[VAL-OPS-038] executes all workout and routine reads from createHevyClient", async () => {
		const fetchMock = vi.fn((input: RequestInfo | URL) => {
			const requestUrl =
				input instanceof Request
					? input.url
					: input instanceof URL
						? input.href
						: input;
			const url = new URL(requestUrl);

			switch (url.pathname) {
				case "/v1/workouts":
					return Promise.resolve(
						response({
							page: 1,
							page_count: 1,
							workouts: [{ id: "workout-1" }],
						}),
					);
				case "/v1/workouts/workout-1":
					return Promise.resolve(response({ id: "workout-1" }));
				case "/v1/routines":
					return Promise.resolve(
						response({
							page: 1,
							page_count: 1,
							routines: [{ id: "routine-1" }],
						}),
					);
				case "/v1/routines/routine-1":
					return Promise.resolve(response({ routine: { id: "routine-1" } }));
				default:
					return Promise.resolve(response({}, 404));
			}
		});
		const operations = createOperations(
			createHevyClient({
				apiKey: "test-key",
				baseUrl: "https://example.test",
				fetch: fetchMock,
				maxGetRetries: 0,
			}),
		);

		await expect(
			operations.workouts.list.execute({ page: 1, pageSize: 5 }),
		).resolves.toEqual({
			items: [{ id: "workout-1" }],
			page: 1,
			pageCount: 1,
		});
		await expect(
			operations.workouts.get.execute({ workoutId: "workout-1" }),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});
		await expect(
			operations.routines.list.execute({ page: 1, pageSize: 5 }),
		).resolves.toEqual({
			items: [{ id: "routine-1" }],
			page: 1,
			pageCount: 1,
		});
		await expect(
			operations.routines.get.execute({ routineId: "routine-1" }),
		).resolves.toEqual({
			routine: { id: "routine-1" },
		});

		expect(fetchMock).toHaveBeenCalledTimes(4);
	});

	it("rejects a Promise-only structural mock with a clear seam error", async () => {
		const client = {
			getWorkouts: vi.fn().mockResolvedValue({ workouts: [] }),
			getWorkout: vi.fn().mockResolvedValue({ id: "workout-1" }),
			getRoutines: vi.fn().mockResolvedValue({ routines: [] }),
			getRoutineById: vi.fn().mockResolvedValue({
				routine: { id: "routine-1" },
			}),
		};
		const operations = createOperations(client as never);

		await expect(
			operations.workouts.get.execute({ workoutId: "workout-1" }),
		).rejects.toThrow("internal request Effect seam");
	});

	it("rejects a malformed requestEffect property with the same clear error", async () => {
		const operations = createOperations({
			getWorkouts: vi.fn(),
			getWorkout: vi.fn(),
			getRoutines: vi.fn(),
			getRoutineById: vi.fn(),
